type ApiError = { error?: string; message?: string };
async function apiError(response: Response) { if(response.status===401)return 'احراز هویت ناموفق بود یا نشست شما منقضی شده است. دوباره تلاش کنید.';if(response.status===403)return 'برای این عملیات دسترسی کافی ندارید.';if(response.status===429)return 'تعداد تلاش‌ها زیاد است؛ کمی بعد دوباره امتحان کنید.';if(response.status===400)return 'درخواست معتبر نیست؛ اطلاعات را بررسی و دوباره تلاش کنید.';if(response.status===409)return 'این عملیات با وضعیت فعلی حساب سازگار نیست.';try { const body = await response.json() as ApiError; return body.error ?? body.message ?? 'درخواست انجام نشد.'; } catch { return 'ارتباط با سامانه برقرار نشد.'; } }

function decodeBase64Url(value: string): ArrayBuffer {
 const normalized=value.replace(/-/g,'+').replace(/_/g,'/');
 const binary=atob(normalized+'='.repeat((4-normalized.length%4)%4));
 const bytes=new Uint8Array(binary.length);
 for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
 return bytes.buffer;
}
function encodeBase64Url(value: ArrayBuffer): string {
 const bytes=new Uint8Array(value);let binary='';
 for(let i=0;i<bytes.length;i++)binary+=String.fromCharCode(bytes[i]!);
 return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
}
function decodeCredentialDescriptors<T extends {id:string;type:PublicKeyCredentialType;transports?:AuthenticatorTransport[]}>(items:T[]|undefined):PublicKeyCredentialDescriptor[]|undefined {
 return items?.map(item=>({id:decodeBase64Url(item.id),type:item.type,...(item.transports?{transports:item.transports}:{})}));
}
function serializeAssertion(credential:PublicKeyCredential):string {
 const response=credential.response as AuthenticatorAssertionResponse;
 return JSON.stringify({id:credential.id,rawId:encodeBase64Url(credential.rawId),type:credential.type,authenticatorAttachment:credential.authenticatorAttachment,response:{clientDataJSON:encodeBase64Url(response.clientDataJSON),authenticatorData:encodeBase64Url(response.authenticatorData),signature:encodeBase64Url(response.signature),userHandle:response.userHandle?encodeBase64Url(response.userHandle):null},clientExtensionResults:credential.getClientExtensionResults()});
}
function serializeAttestation(credential:PublicKeyCredential):string {
 const response=credential.response as AuthenticatorAttestationResponse;
 return JSON.stringify({id:credential.id,rawId:encodeBase64Url(credential.rawId),type:credential.type,authenticatorAttachment:credential.authenticatorAttachment,response:{clientDataJSON:encodeBase64Url(response.clientDataJSON),attestationObject:encodeBase64Url(response.attestationObject),transports:response.getTransports?.()??[]},clientExtensionResults:credential.getClientExtensionResults()});
}
function requireWebAuthn():void {
 if(!window.isSecureContext||!navigator.credentials||typeof PublicKeyCredential==='undefined')throw new Error('ورود با کلید عبور فقط در مرورگر سازگار و اتصال امن HTTPS در دسترس است.');
}
function errorMessage(error:unknown,fallback:string,setAdmin:(admin:Admin|null)=>void,setTotpSetup:(setup:TotpSetup|null)=>void,setTotpSetupCode:(code:string)=>void):string {
 const message=error instanceof Error?error.message:fallback;
 if(message.startsWith('احراز هویت ناموفق بود یا نشست شما منقضی شده است.')){setAdmin(null);setTotpSetup(null);setTotpSetupCode('');}
 return message;
}
