 async function passkeyLogin(){if(busy)return;setBusy(true);setError('');setNotice('');try{requireWebAuthn();const csrf=await token();const optionResponse=await fetch('/api/auth/passkey/options',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({userName:userName.trim()||null})});if(!optionResponse.ok)throw new Error(await apiError(optionResponse));const json=await optionResponse.json() as PasskeyRequestOptionsJson;const {challenge,allowCredentials,...rest}=json;const options:PublicKeyCredentialRequestOptions={...rest,challenge:decodeBase64Url(challenge),...(allowCredentials?{allowCredentials:decodeCredentialDescriptors(allowCredentials as unknown as Array<{id:string;type:PublicKeyCredentialType;transports?:AuthenticatorTransport[]}>)!}:{})};const credential=await navigator.credentials.get({publicKey:options});if(!credential||!(credential instanceof PublicKeyCredential))throw new Error('تأیید کلید عبور انجام نشد.');const verify=await fetch('/api/auth/passkey/sign-in',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({credentialJson:serializeAssertion(credential)})});if(!verify.ok)throw new Error(await apiError(verify));const me=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'});if(!me.ok)throw new Error('نشست معتبر پس از تأیید کلید عبور ایجاد نشد.');setAdmin(await me.json() as Admin);setPassword('');setCode('')}catch(err){setError(err instanceof DOMException&&err.name==='NotAllowedError'?'درخواست کلید عبور لغو شد یا زمان آن پایان یافت.':err instanceof Error?err.message:'ورود با کلید عبور ناموفق بود.')}finally{setBusy(false)}}
 async function registerPasskey(){if(busy)return;setBusy(true);setError('');setNotice('');try{requireWebAuthn();const csrf=await token();const optionResponse=await fetch('/api/auth/passkey/creation-options',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'X-CSRF-TOKEN':csrf}});if(!optionResponse.ok)throw new Error(await apiError(optionResponse));const json=await optionResponse.json() as PasskeyCreationOptionsJson;const {challenge,user,excludeCredentials,...rest}=json;const options:PublicKeyCredentialCreationOptions={...rest,challenge:decodeBase64Url(challenge),user:{...user,id:decodeBase64Url(user.id)},...(excludeCredentials?{excludeCredentials:decodeCredentialDescriptors(excludeCredentials as unknown as Array<{id:string;type:PublicKeyCredentialType;transports?:AuthenticatorTransport[]}>)!}:{})};const credential=await navigator.credentials.create({publicKey:options});if(!credential||!(credential instanceof PublicKeyCredential))throw new Error('ثبت کلید عبور تکمیل نشد.');const register=await fetch('/api/auth/passkey/register',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({credentialJson:serializeAttestation(credential),displayName:'کلید عبور مرورگر'})});if(!register.ok)throw new Error(await apiError(register));const me=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'});if(!me.ok)throw new Error('نشست پس از ثبت کلید عبور معتبر نماند.');setAdmin(await me.json() as Admin);setNotice('کلید عبور با موفقیت ثبت شد.');}catch(err){setError(err instanceof DOMException&&err.name==='NotAllowedError'?'ثبت کلید عبور لغو شد یا زمان آن پایان یافت.':errorMessage(err,'ثبت کلید عبور ناموفق بود.',setAdmin,setTotpSetup,setTotpSetupCode))}finally{setBusy(false)}}
